      "title": "机器人技能学习的鲁棒特征选择及刚度感知方法研究获进展",
      "summary": "首页 > 科研进展 近日，中国科学院宁波材料技术与工程研究所等提出了一种鲁棒特征选择方法，可提升人机协作中的交互刚度估计能力。 随着具身智能和人形机器人走向真实作业场景，机器人不仅需要学习人的运动轨迹，还需要学习动作背后的接触技能，如柔顺性、力适应和刚度调节。在打磨、装配、抛光、擦拭等接触密集型任务中，交互刚度决定机器",
