      "angle": "Turn the research into a human-readable science story about frontier science, research infrastructure and scientific discovery, avoiding claims beyond the published evidence. For this item, test the claim behind “热响应离子液体辅助高盐废水膜浓缩研究获进展” against primary-source evidence.",
