      "matchedTopic": "科学前沿动态",
      "rawText": "首页 > 科研进展 高盐废水主要产生于海水淡化、工业废水处理和非常规能源开发等过程。随着水中盐分浓度升高，废水渗透压力迅速增大，导致传统反渗透水处理技术弊端凸显，较难满足高盐废水深度浓缩的处理需求。 渗透辅助反渗透技术（OARO）为高盐废水浓缩提供了新的膜处理路径。目前，主流的OARO体系多采用无机盐作为汲取液，但后续再生回用汲取液与净化产出净水需要消耗大量电能，限制了其整体能效提升。 近日，中国科学院合肥物质科学研究院提出将可回收的热响应离子液体作为汲取溶质，并引入OARO处理过程，构建了一套热响应离子液体辅助OARO高盐废水浓缩体系。该体系利用离子液体，提供额外渗透驱动力，推动废水浓缩进程；通过低品位余热诱导物质相分离，实现汲取液的循环回用；通过纳滤和反渗透组合工艺去除残留的微量离子液体和盐分，保障产水水质。 研究以具有低临界溶解温度特性的离子液体[P4444][DMBS]为汲取溶质，搭建台式OARO实验系统，在高盐条件下开展了验证实验。结果显示，该体系可稳定处理氯化钠NaCl浓度在1.5至2.5mol/L的高盐废水，且产水通量可达1.5至3L/（m 2 ・h）。 机理分析表明，热",
