      "rawText": "首页 日媒：高市早苗将邀请500名印度人才赴日 分享到： 据日本《每日新闻》6月30日报道，日本首相高市早苗与印度总理莫迪正在协调起稿一份有关人工智能（AI）合作的联合声明，其中提出，在2030年前邀请500名印度高技能人才赴日。 高市早苗将于7月1日至3日访问印度首都新德里，期间的联合声明将提出，加强日印两国在新型AI模型开发上的合作，并促进人才交流。 报道炒作说，此举目的是应对在AI领域处于领先地位的中国，提升日印两国在该领域的影响力。 据介绍，为实现高市早苗本人牵头升级的“自由开放的印度太平洋”愿景，以及莫迪提出的“共同全面促进地区安全与发展”计划，高市此访将加强AI合作作为核心议题。高市还有意吸引更多“志同道合国家及伙伴国”加入合作。 本文系观察者网独家稿件，未经授权，不得转载。 变“牛夫人”了！印度无法像中国抗衡美国，咋整？ 车位被占反遭对方报警，为什么守规矩的人维权这么累？ 美银：苹果或将长鑫存储作为谈判筹码 “中国石油需求将在今年达到峰值” 高市被迫改变强硬立场 曾被中方制裁的荷兰大臣访华，要谈啥？ 想与中国签自贸协定？“巴拉圭不回头，可能性几乎为零” 茉莉奶白捐百万，网",
