  "displayBriefingHtml": "\n    <div class=\"brief-display\">\n      <h3>CGTN Tech Desk Daily Radar <small>V3</small></h3>\n      <p><strong>ChenChen 今日中国科技热点</strong>｜Reporter Mode｜硬科技优先</p>\n      <p>日期：2026-07-07｜生成时间：2026/7/7 18:02:14｜抓取时间范围：00:00–当前时间</p>\n      <p>数据统计：抓取总数 2577｜确认今日 74｜国际背景 8</p>\n      <h4>本次更新</h4>\n      <p>新增核心线索：国内 8 条｜国际 0 条<br>延续跟踪线索：国内 66 条｜国际 8 条<br>本次有新增核心线索，优先核验新增项的一手来源和可视化素材。</p>\n      <h4>最值得关注</h4>\n      \n    <article class=\"brief-item\">\n      <strong>1. [2026-07-07] 机器人技能学习的鲁棒特征选择及刚度感知方法研究获进展</strong>\n      <span>中国科学院｜2026-07-07｜<a href=\"https://www.cas.cn/syky/202607/t20260707_5114755.shtml\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <span>硬科技优先级：90｜记者分：220｜一手来源</span>\n      <p>报道角度：Assess the robotics value chain through embodied intelligence beyond demonstration, including components, cost, reliability and export potential. For this item, test the claim behind “机器人技能学习的鲁棒特征选择及刚度感知方法研究获进展” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>2. [2026-07-07] 凯文·凯利将亮相WAIC与荣耀探讨Agentic OS演进路径，荣耀Robot Phone率先落地部分功能</strong>\n      <span>新浪科技｜2026-07-07｜<a href=\"https://finance.sina.com.cn/roll/2026-07-07/doc-inifyqva5196124.shtml\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <span>硬科技优先级：95｜记者分：198｜需核验来源</span>\n      <p>报道角度：Turn the item into a reporting test of deployment evidence and productivity gains: capability, implementation, economic value and regulatory consequences. For this item, test the claim behind “凯文·凯利将亮相WAIC与荣耀探讨Agentic OS演进路径，荣耀Robot Phone率先落地部分功能” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>3. [2026-07-07] 瞭望智库组织探讨AI算力坚守长期自主创新的破局之道</strong>\n      <span>人民网-科技｜2026-07-07｜<a href=\"http://finance.people.com.cn/n1/2026/0707/c1004-40754664.html\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <span>硬科技优先级：95｜记者分：206｜一手来源</span>\n      <p>报道角度：Use AI-compute demand and domestic alternatives as the spine of the story, then compare China’s progress with global competitors and market demand. For this item, test the claim behind “瞭望智库组织探讨AI算力坚守长期自主创新的破局之道” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>4. [2026-07-07] 在“从0到1”的地方，做“从0到1”的创新</strong>\n      <span>光明网-科技｜2026-07-07｜<a href=\"https://tech.gmw.cn/2026-07/07/content_38871348.htm\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <span>硬科技优先级：90｜记者分：193｜需核验来源</span>\n      <p>报道角度：Assess the robotics value chain through robotics, embodied intelligence and smart manufacturing, including components, cost, reliability and export potential. For this item, test the claim behind “在“从0到1”的地方，做“从0到1”的创新” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>5. [2026-07-07] 产业年均增速超20% 2026世界机器人大会8月启幕</strong>\n      <span>人民网-科技｜2026-07-07｜<a href=\"http://finance.people.com.cn/n1/2026/0707/c1004-40755020.html\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <span>硬科技优先级：90｜记者分：203｜一手来源</span>\n      <p>报道角度：Show whether the robot is moving from demo to deployment, using robotics, embodied intelligence and smart manufacturing, orders, operating scenarios and safety as evidence. For this item, test the claim behind “产业年均增速超20% 2026世界机器人大会8月启幕” against primary-source evidence.</p>\n    </article>\n  \n      <h4>国际科技背景</h4>\n      \n    <article class=\"brief-item\">\n      <strong>1. Insert token to continue, says AI. Yeah, about that</strong>\n      <span>时间：Mon, 06 Jul 2026 10:30:00 +0200｜来源：The Register｜<a href=\"https://www.theregister.com/columnists/2026/07/06/insert-token-to-continue-says-ai-yeah-about-that/5266319\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <p>Frame this as an AI deployment story about AI applications, foundation models, agents and governance, separating product claims from evidence of real-world adoption. For this item, test the claim behind “Insert token to continue, says AI. Yeah, about that” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>2. Your family’s $300 stake in OpenAI</strong>\n      <span>时间：Mon, 06 Jul 2026 18:00:00 +0000｜来源：MIT Technology Review｜<a href=\"https://www.technologyreview.com/2026/07/06/1140176/your-familys-300-stake-in-openai/\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <p>Turn the item into a reporting test of AI applications, foundation models, agents and governance: capability, implementation, economic value and regulatory consequences. For this item, test the claim behind “Your family’s $300 stake in OpenAI” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>3. Secret Claude tracker shocks users after Anthropic’s anti-surveillance stance</strong>\n      <span>时间：Mon, 06 Jul 2026 16:44:18 +0000｜来源：Ars Technica｜<a href=\"https://arstechnica.com/tech-policy/2026/07/anthropic-outed-for-claude-tracker-that-secretly-monitored-chinese-users/\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <p>Ask whether this changes China’s AI competitiveness through AI applications, foundation models, agents and governance, and identify users, costs, safeguards and export relevance. For this item, test the claim behind “Secret Claude tracker shocks users after Anthropic’s anti-surveillance s” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>4. Samsung floats 2028 launch for seaborne datacenter</strong>\n      <span>时间：Mon, 06 Jul 2026 18:34:00 +0200｜来源：The Register｜<a href=\"https://www.theregister.com/on-prem/2026/07/06/samsung-floats-2028-launch-for-seaborne-datacenter/5266981\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <p>Report beyond the announcement: verify yield, scale, customers and how semiconductors, advanced manufacturing and compute infrastructure affects industrial resilience. For this item, test the claim behind “Samsung floats 2028 launch for seaborne datacenter” against primary-source evidence.</p>\n    </article>\n  \n    <article class=\"brief-item\">\n      <strong>5. If you use Google, you’re training its AI. Here’s how to opt out.</strong>\n      <span>时间：Mon, 06 Jul 2026 17:04:58 +0000｜来源：TechCrunch｜<a href=\"https://techcrunch.com/2026/07/06/if-you-use-google-youre-training-its-ai-heres-how-to-opt-out/\" target=\"_blank\" rel=\"noopener\">原文链接</a></span>\n      <p>Lead with AI applications, foundation models, agents and governance; verify who is using the system, what measurable gains exist and where governance risks remain. For this item, test the claim behind “If you use Google, you’re training its AI. Here’s how to opt out.” against primary-source evidence.</p>\n    </article>\n  \n    </div>\n  ",
